"""Questões que faltavam nas provas em escada de Português (Pablo, 18/11/2026: "subia de
nível, fazia algo mais complexo... com esse conteúdo você consegue ainda resolver a
questão, só que tem que pensar mais"; o peso de 20 kg). Textos originais, escritos
aqui. Nível `acima` = estilo ITA/IME/Fuvest, nunca apresentado como real.
Sem conta: a aula usa "A regra desta questão" e "A regra em palavras", com pistas
no lugar das letras. Gravar: scripts/criar-provas-escada.ts."""

ARQUIVO = '../escada/portugues'


def P(tema, nivel):
  return {'materia': 'Português', 'tema': tema, 'nivel': nivel}


INT, GEN, VAR = 'Interpretação de Texto', 'Gêneros Textuais e Multimodalidade', 'Variação Linguística e Norma-Padrão'
GRA, FIG, LIT = 'Gramática e Coesão', 'Funções e Figuras de Linguagem', 'Literatura Brasileira'


def aula(regras, tenho, quer, regra, porque, letras, telas, volta, valores, pista, receita):
  """Molde do robô sem conta: a regra pronta, as pistas do texto, uma tela por pista."""
  return dict(
    titulo_formulas='A regra desta questão', formulas_texto='Esta é a regra que a questão usa. Já está pronta: é só usar.',
    formulas=regras, tenho_texto='Primeiro, separe as pistas do enunciado.', tenho=tenho,
    titulo_regra='A regra em palavras', quer=quer, equacao=regra, porque=porque, agora='Agora é só achar cada pista.',
    letras=letras, telas=[dict(titulo=t, texto=x) for t, x in telas], volta=volta, valores=valores, pista=pista,
    receita=[('1. Separe as pistas', receita[0]), ('2. A regra em palavras', receita[1]), ('3. Ache cada pista', receita[2]), ('4. Compare com as letras', receita[3])])


