    [('Achando P1 (opina?)', '"Critica a demora" = opina. A letra A cai.'),
     ('Achando P2: o seu jeito', 'Parece certo pensar que, sem assinatura, foi um leitor. Mas carta de leitor vem com o nome dele.\nSem nome nenhum, quem fala é o jornal: P2 = o veículo.')],
