  conferencia='Mesma coisa, nomes diferentes por região = variação regional. E. A = não há mudança de época; B = não há classe social; C = os três servem em qualquer situação; D não é tipo de variação.',
  sua_vez=('"Vossa mercê" virou "você" com o tempo. É variação:', ['Histórica', 'Regional', 'Social', 'Situacional'], 'Histórica', 'Mudou de uma época para outra.'),
