    [('Achando P: o seu jeito', 'Parece certo marcar a E, porque "pharmacia" parece erro hoje. Mas em 1890 se escrevia assim.\nO que separa as frases: P = mais de um século.')],
    'R = variação histórica\nLetra A.', [('P', 'a época')],
